@isTest private class CurrentBaseMetadataDtoDeterministic004Test {
    @isTest static void metadataDtoDeterministic004Witness() {
        Metadata.QuickActionList quickActionList = new Metadata.QuickActionList();
        System.assertNotEquals(null, quickActionList);
        quickActionList.quickActionListItems = new List<Metadata.QuickActionListItem>{new Metadata.QuickActionListItem()};
        System.assertEquals(1, quickActionList.quickActionListItems.size());

        Metadata.QuickActionListItem quickActionListItem = new Metadata.QuickActionListItem();
        System.assertNotEquals(null, quickActionListItem);
        quickActionListItem.quickActionName = 'Account.NewQuickAction';
        System.assertEquals('Account.NewQuickAction', quickActionListItem.quickActionName);

        Metadata.RelatedContent relatedContent = new Metadata.RelatedContent();
        System.assertNotEquals(null, relatedContent);
        relatedContent.relatedContentItems = new List<Metadata.RelatedContentItem>{new Metadata.RelatedContentItem()};
        System.assertEquals(1, relatedContent.relatedContentItems.size());

        Metadata.RelatedContentItem relatedContentItem = new Metadata.RelatedContentItem();
        System.assertNotEquals(null, relatedContentItem);
        relatedContentItem.layoutItem = new Metadata.LayoutItem();
        System.assertNotEquals(null, relatedContentItem.layoutItem);

        Metadata.RelatedList relatedList = new Metadata.RelatedList();
        System.assertNotEquals(null, relatedList);
        relatedList.hideOnDetail = true;
        relatedList.name = 'Contacts';
        System.assertEquals(true, relatedList.hideOnDetail);
        System.assertEquals('Contacts', relatedList.name);

        Metadata.RelatedListItem relatedListItem = new Metadata.RelatedListItem();
        System.assertNotEquals(null, relatedListItem);
        relatedListItem.customButtons = new List<String>{'New'};
        relatedListItem.excludeButtons = new List<String>{'Delete'};
        relatedListItem.fields = new List<String>{'Name'};
        relatedListItem.quickActions = new List<String>{'Account.NewQuickAction'};
        relatedListItem.relatedList = 'Contacts';
        relatedListItem.sortField = 'Name';
        relatedListItem.sortOrder = Metadata.SortOrder.Asc_x;
        System.assertEquals('New', relatedListItem.customButtons[0]);
        System.assertEquals('Delete', relatedListItem.excludeButtons[0]);
        System.assertEquals('Name', relatedListItem.fields[0]);
        System.assertEquals('Account.NewQuickAction', relatedListItem.quickActions[0]);
        System.assertEquals('Contacts', relatedListItem.relatedList);
        System.assertEquals('Name', relatedListItem.sortField);
        System.assertEquals(true, Metadata.SortOrder.Asc_x.equals(relatedListItem.sortOrder));

        Metadata.ReportChartComponentLayoutItem chart = new Metadata.ReportChartComponentLayoutItem();
        System.assertNotEquals(null, chart);
        chart.cacheData = true;
        chart.contextFilterableField = 'Account.Name';
        chart.error = 'error';
        chart.hideOnError = true;
        chart.includeContext = true;
        chart.reportName = 'MyReport';
        chart.showTitle = true;
        chart.size = Metadata.ReportChartComponentSize.LARGE;
        System.assertEquals(true, chart.cacheData);
        System.assertEquals('Account.Name', chart.contextFilterableField);
        System.assertEquals('error', chart.error);
        System.assertEquals(true, chart.hideOnError);
        System.assertEquals(true, chart.includeContext);
        System.assertEquals('MyReport', chart.reportName);
        System.assertEquals(true, chart.showTitle);
        System.assertEquals(true, Metadata.ReportChartComponentSize.LARGE.equals(chart.size));

        Metadata.ReportChartComponentSize large = Metadata.ReportChartComponentSize.LARGE;
        Metadata.ReportChartComponentSize medium = Metadata.ReportChartComponentSize.MEDIUM;
        Metadata.ReportChartComponentSize small = Metadata.ReportChartComponentSize.SMALL;
        System.assertEquals(true, large.equals(large));
        System.assertNotEquals(null, large.hashCode());
        System.assertEquals(0, large.ordinal());
        System.assertEquals(true, Metadata.ReportChartComponentSize.valueOf('LARGE').equals(large));
        System.assertEquals(3, Metadata.ReportChartComponentSize.values().size());
        System.assertEquals('LARGE', String.valueOf(large));
        System.assertEquals('MEDIUM', String.valueOf(medium));
        System.assertEquals('SMALL', String.valueOf(small));

        Metadata.SidebarComponent sidebar = new Metadata.SidebarComponent();
        System.assertNotEquals(null, sidebar);
        sidebar.componentType = 'Custom';
        sidebar.createAction = 'New';
        sidebar.enableLinking = true;
        sidebar.height = 100;
        sidebar.knowledgeOneEnable = false;
        System.assertEquals('Custom', sidebar.componentType);
        System.assertEquals('New', sidebar.createAction);
        System.assertEquals(true, sidebar.enableLinking);
        System.assertEquals(100, sidebar.height);
        System.assertEquals(false, sidebar.knowledgeOneEnable);

        System.assertNotEquals(null, quickActionList.clone());
        System.assertNotEquals(null, quickActionListItem.clone());
        System.assertNotEquals(null, relatedContent.clone());
        System.assertNotEquals(null, relatedContentItem.clone());
        System.assertNotEquals(null, relatedList.clone());
        System.assertNotEquals(null, relatedListItem.clone());
        System.assertNotEquals(null, chart.clone());
        System.assertNotEquals(null, sidebar.clone());
    }
}
